      unexpectedBetweenGenericWhereClauseAndMemberBlock?.raw,
      memberBlock: memberBlock.raw,
      unexpectedAfterMemberBlock?.raw,
      arena: arena
    ))
  }

  var unexpectedBeforeAttributes: RawUnexpectedNodesSyntax? {
